COL_USER_ID              = 0
COL_USER_COUNTRY         = 1
COL_PACKAGENAME          = 2
COL_CATEGORY             = 3
COL_CATEGORYNAME         = 4
COL_LAN                  = 5
COL_STATUS               = 6
COL_TOKENS               = 7
COL_DOWNLOAD             = 8
COL_EXPOSE7D             = 9
