def test_dense_width_is3(fe):
    result = fe.run(build_user_feats(), {}, [])
    assert result["dense"].shape[1] == 3


def test_sparse_count_is14(fe):
    result = fe.run(build_user_feats(), {}, [])
    assert len(result["sparse"]) == 14


